import {NAMING_DATA as data} from './mj-naming-data';

/** Unified Chinese naming (generated by scripts/prepare-naming.mjs): priority is docs/muscle-layers.json, then docs/glossary.json 跑考摘要, then other glossary entries, then the Taiwan-standard tables. */
/** Mesh names from the GLB look like "Greater occipital nerve.l.001"; turn them into "Left Greater occipital nerve". */
export function cleanMeshName(name:string){
 let n=name.trim();
 const m=/^(.*?)\.([lr])(?:\.\d+)?$/i.exec(n);
 if(m)n=(m[2].toLowerCase()==='l'?'Left ':'Right ')+m[1];
 return n.replace(/[. ]0\d\d$/,'').replace(/\*$/,'').trim();
}
export const namingKey=(name:string)=>cleanMeshName(name).toLowerCase().replace(/\b(?:left|right)\b/g,' ').replace(/(?:^|\.)[lr](?=\.|$)/g,' ').replace(/[._]+/g,' ').replace(/\s+/g,' ').trim().replace(/ muscle$/,'');

const overrides=data.overrides as Record<string,string>;
export const namingOverride=(name:string):string|undefined=>overrides[namingKey(name)];

/** Wrong or non-standard forms that must never be shown (confirmed corrections). */
export const ZH_FIXES:[string,string][]=data.fixes as [string,string][];
export const applyZhFixes=(zh:string)=>ZH_FIXES.reduce((s,[from,to])=>s.split(from).join(to),zh);
